package com.projecteden.visit.controller;
import java.util.List; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.projecteden.user.domain.User; import com.projecteden.visit.dto.VisitResponseDTO; import com.projecteden.visit.service.IslandVisitService;
@RestController @RequestMapping("/api/visits") public class IslandVisitController { private final IslandVisitService service; public IslandVisitController(IslandVisitService service){this.service=service;} @PostMapping("/{friendId}") public VisitResponseDTO visit(@AuthenticationPrincipal User u,@PathVariable Long friendId){return service.visitIsland(u.getId(),friendId);} @GetMapping("/history") public List<VisitResponseDTO> history(@AuthenticationPrincipal User u){return service.history(u.getId());} }
